inline const ApiRule& apiRule(std::string_view api)
{
    for (const ApiRule& r : kApiRules)
        if (api == r.api)
            return r;
    throw std::invalid_argument(std::string("unknown API ") + std::string(api));
}

inline const TypeRule& typeRule(std::string_view type)
{
    for (const TypeRule& r : kTypeRules)
        if (type == r.type)
            return r;
    throw std::invalid_argument(std::string("unknown prim type ") + std::string(type));
}

/// Base API id of a possibly qualified `Name:instance` schema token.
inline std::string baseApi(std::string_view schema) { return std::string(schema.substr(0, schema.find(':'))); }

/// Column name of a multi-apply API for one instance: every `<inst>` replaced.
inline std::string instanced(std::string_view column, std::string_view instance)
{
    std::string out(column);
    for (size_t pos = out.find("<inst>"); pos != std::string::npos; pos = out.find("<inst>", pos + instance.size()))
        out.replace(pos, 6, instance);
    return out;
}

inline ovx_string_t str(std::string_view s) { return ovx_string_t{ s.data(), s.size() }; }

inline void check(path_dictionary_instance_t* dict, ovx_api_result_t r, const char* what)
{
    if (r.status == OVX_API_SUCCESS)
        return;
    std::string msg = std::string(what) + " failed";
    if (r.error.ptr)
    {
        msg += ": ";
        msg.append(r.error.ptr, r.error.length);
        path_dictionary_release_error(dict, r.error);
    }
    throw std::runtime_error(msg);
}

inline std::string opError(ovstage_instance_t* instance, ovstage_op_id_t op)
{
    const ovx_string_t s = ovstage_get_last_op_error(instance, op);
    return s.ptr && s.length ? std::string(s.ptr, s.length) : std::string("(no error text)");
}

/// Wait for an enqueued op and retire it. Enqueue success only means accepted: execution failures
/// of the op, or of a producer in its dependency chain, arrive in the wait result's error_op_ids
/// (the first id carries the root cause). The op is released only once the wait completed.
inline void waitOp(ovstage_instance_t* instance, ovstage_enqueue_result_t r, const char* what)
{
    if (r.status != OVSTAGE_OK)
        throw std::runtime_error(std::string(what) + " failed to enqueue: " + ovstage_get_error_string(instance, r.status));
    if (r.op_index == OVSTAGE_INVALID_OP_ID)
        return;
    ovstage_op_wait_result_t result{};
    const ovstage_api_status_t status = ovstage_wait_op(instance, r.op_index, OVSTAGE_TIMEOUT_INFINITE, &result);
    if (status != OVSTAGE_OK || result.error_op_id_count != 0)
    {
        const ovstage_op_id_t failed = result.error_op_id_count ? result.error_op_ids[0] : r.op_index;
        const std::string message = std::string(what) + " failed: " + opError(instance, failed);
        if (status != OVSTAGE_ERROR_TIMEOUT)
            ovstage_release_op(instance, r.op_index); // completed (with errors): safe to retire
        throw std::runtime_error(message);
    }
    ovstage_release_op(instance, r.op_index);
}

/// Unwinding variant: wait, then retire; never throws, never releases a still-pending op.
inline void waitOpNoThrow(ovstage_instance_t* instance, ovstage_enqueue_result_t r) noexcept
{
    if (r.status != OVSTAGE_OK || r.op_index == OVSTAGE_INVALID_OP_ID)
        return;
    ovstage_op_wait_result_t result{};
    if (ovstage_wait_op(instance, r.op_index, OVSTAGE_TIMEOUT_INFINITE, &result) != OVSTAGE_ERROR_TIMEOUT)
        ovstage_release_op(instance, r.op_index);
}

// Scope guards so a throwing write releases its path list and query instead of leaking them.
struct PathListGuard
{
    path_dictionary_instance_t* dict;
    ovx_primpath_list_t list;
    ~PathListGuard() { if (list != OVX_INVALID_PRIMPATH_LIST) path_dictionary_release_path_list_reference(dict, list); }
};
struct QueryGuard
{
    ovstage_instance_t* instance;
    ovstage_query_handle_t query;
    void release() // the handle is disarmed first: a throwing wait must not make the destructor release it again
    {
        const ovstage_query_handle_t q = query;
        query = OVSTAGE_INVALID_QUERY_HANDLE;
        if (q != OVSTAGE_INVALID_QUERY_HANDLE)
            waitOp(instance, ovstage_release_query(instance, q), "ovstage_release_query");
    }
    ~QueryGuard() // unwinding: release the query, wait for it, retire the op; never throws
    {
        if (query != OVSTAGE_INVALID_QUERY_HANDLE)
            waitOpNoThrow(instance, ovstage_release_query(instance, query));
    }
};

